import {properties,reportingRange,csv} from './model.mjs';
import {channels,platforms,selectWebsite,websiteSummary,websiteBreakdown,websiteTrend,websiteExportRows,seedAccounts,restoreAccounts,validateAccount,selectAccounts,socialRows,socialSummary,socialPosts,socialFeedSelection,socialExportRows,accountCoverage} from './digital-model.mjs';
import {displaySwitch,displayMode} from './display-views.mjs';

export function createDigitalWorkspace({esc,btn,chip,heading,panel,metric,table,td,num,pct,filters,render,navigate,openDialog,closeDialog,toast}){
 const KEY='mf-hub-digital-accounts-v1';
 let accounts=seedAccounts(),kind='website',tab='overview',local={range:'10',dateFrom:'2026-10-01',dateTo:'2026-10-31',channel:'all',platform:'all',account:'all'};
 let feedSearch='',feedFormat='all',feedPage=0,feedSignature='';
 try{const saved=localStorage.getItem(KEY);if(saved)accounts=restoreAccounts(JSON.parse(saved));}catch{}
 const scope=()=>({...filters,dateFrom:local.dateFrom,dateTo:local.dateTo,...(kind==='website'?{channel:local.channel}:{platform:local.platform,account:local.account})});
 const options=(rows,value)=>rows.map(([id,name])=>`<option value="${esc(id)}" ${id===String(value)?'selected':''}>${esc(name)}</option>`).join('');
 const select=(id,label,value,rows,global=false)=>`<div class="filter"><label for="digital-${id}">${label}</label><select id="digital-${id}" ${global?'data-filter':'data-digital'}="${id}">${options(rows,value)}</select></div>`;
 const tabs=(module,items)=>`<nav class="tabs" aria-label="${module==='website'?'Website analytics':'Social media'} views">${items.map(([id,name])=>btn(name,'navigate',`data-route="${module}/${id}" ${tab===id?'aria-current="page"':''}`,`tab ${tab===id?'active':''}`)).join('')}</nav>`;
 function controls(){const available=selectAccounts(accounts,{...scope(),account:'all'});return `<section class="digital-filters" aria-label="${kind==='website'?'Website':'Social media'} filters"><div class="filters">${select('pmc','Management company',filters.pmc,[['all','All companies'],...[...new Set(properties.map(p=>p.pmc))].map(n=>[n,n])],true)}${select('city','City',filters.city,[['all','All cities'],...[...new Set(properties.map(p=>p.city))].map(n=>[n,n])],true)}${select('property','Property',filters.property,[['all','All properties'],...properties.map(p=>[p.id,p.name])],true)}${select('range','Activity dates',local.range,[['10','October 2026'],['9','September 2026'],['all','Sep–Oct 2026'],['custom','Custom dates']])}${kind==='website'?select('channel','Session channel',local.channel,[['all','All channels'],...channels.map(n=>[n,n])]):select('platform','Platform',local.platform,[['all','All platforms'],...platforms.map(n=>[n,n])])}${kind==='social'?select('account','Account / handle',local.account,[['all','All accounts'],...available.map(a=>[a.id,a.label+' · @'+a.handle])]):''}${btn('Reset','digital-reset','','secondary')}${btn(kind==='social'&&tab==='feed'?'Export matching posts':kind==='social'&&tab==='accounts'?'Export mappings':'Export report','digital-export','','secondary')}</div>${local.range==='custom'?`<form id="digital-dates" class="marketing-dates"><div class="filter"><label for="digital-from">Start date</label><input id="digital-from" name="dateFrom" type="date" required value="${local.dateFrom}"></div><div class="filter"><label for="digital-to">End date</label><input id="digital-to" name="dateTo" type="date" required value="${local.dateTo}"></div><button class="btn" type="submit">Apply dates</button><p class="date-error" role="alert"></p></form>`:''}<p class="filter-note">${local.dateFrom} – ${local.dateTo} · Website visits and social activity in this period; separate from the lead-creation cohort. Fictional sample available Sep–Oct 2026.</p></section>`;}
 function bars(title,sub,rows,key='activeUsers',dimension=''){const max=Math.max(1,...rows.map(r=>r[key])),totals=websiteSummary(selectWebsite(scope())),denominator=key==='sessions'?totals.sessions:key==='newUsers'?totals.newUsers:totals.activeUsers;return panel(title,sub,rows.length?`<div class="digital-bars">${rows.map(r=>`<button type="button" class="digital-bar" data-action="digital-breakdown" data-dimension="${esc(dimension)}" data-label="${esc(r.label)}"><span>${esc(r.label)}</span><span class="digital-track"><span style="width:${r[key]/max*100}%"></span></span><strong>${num(r[key])}<small>${pct(r[key],denominator)} of ${key==='sessions'?'sessions':key==='newUsers'?'new users':'active users'}</small></strong></button>`).join('')}</div>`:'<div class="empty">No activity in this selection.</div>');}
 function chart(title,subtitle,points,measure=kind==='website'?'Sessions':'Content / listing views'){if(!points.length)return panel(title,subtitle,'<div class="empty">No activity in this selection.</div>');const max=Math.max(1,...points.map(p=>p.value)),x=i=>45+i*520/Math.max(1,points.length-1),y=v=>155-v/max*125;return panel(title,subtitle,`<svg class="digital-chart" viewBox="0 0 600 195" role="img" aria-label="${esc(title)}. ${points.map(p=>p.label+': '+p.value).join('; ')}">${[0,.5,1].map(f=>`<line x1="45" x2="565" y1="${y(max*f)}" y2="${y(max*f)}" stroke="#e3eaf0"/><text x="3" y="${y(max*f)+4}">${num(max*f)}</text>`).join('')}<polygon points="45,155 ${points.map((p,i)=>x(i)+','+y(p.value)).join(' ')} 565,155" fill="var(--brand)" opacity=".08"/><polyline points="${points.map((p,i)=>x(i)+','+y(p.value)).join(' ')}" stroke="var(--brand)" stroke-width="3" fill="none"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="3" fill="var(--brand)"><title>${esc(p.label)}: ${num(p.value)}</title></circle>${i===0||i===points.length-1||i===Math.floor(points.length/2)?`<text x="${x(i)}" y="182" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}">${esc(p.label)}</text>`:''}`).join('')}</svg><details class="digital-data"><summary>View chart data</summary>${table(['Date','#'+measure],points.map(p=>'<tr>'+td(esc(p.date||p.label))+td(num(p.value),true)+'</tr>'))}</details>`);}
 function website(tabName){kind='website';tab=['overview','demographics','technology','acquisition'].includes(tabName)?tabName:'overview';const rows=selectWebsite(scope()),s=websiteSummary(rows),b=key=>websiteBreakdown(rows,key),sub='Active users · click a row for details';let body='';
 if(tab==='overview')body=`<div class="metrics">${metric('Active users',num(s.activeUsers),'Distinct sample visitors','people','digital-breakdown','data-dimension="all"')}${metric('Sessions',num(s.sessions),'Website visits in this period','globe','digital-breakdown','data-dimension="all"')}${metric('Engagement rate',pct(s.engaged,s.sessions),'Engaged sessions ÷ sessions','chart','digital-breakdown','data-dimension="all"')}${metric('Key events',num(s.keyEvents),'Sample enquiry / tour actions','target','digital-breakdown','data-dimension="all"')}</div><div class="grid equal">${chart('Website traffic','Daily sessions for the selected websites and dates.',websiteTrend(rows,scope()))}${bars('Acquisition snapshot','Sessions by session channel.',b('channel'),'sessions','channel')}</div><div class="grid equal">${panel('New & returning visitors','Users can be new and return during the same period.',`${userMix(s)}<p class="footnote">These audiences overlap; do not add them together.</p>`)}${panel('Explore your website audience','Go from traffic volume to the people and devices behind it.',`<div class="digital-shortcuts">${btn('Demographic overview →','navigate','data-route="website/demographics"','secondary')}${btn('Technology overview →','navigate','data-route="website/technology"','secondary')}${btn('Acquisition overview →','navigate','data-route="website/acquisition"','secondary')}</div>`)}</div>${bars('Landing pages','Sessions starting on each page.',b('page'),'sessions','page')}`;
 if(tab==='demographics')body=`<div class="notice">Demographics can be unknown or withheld in live GA4 reports. This demo includes Unknown; interests overlap and are not additive. Demographics are for aggregate audience reporting.</div><div class="grid equal">${bars('Age overview',sub,b('age'),'activeUsers','age')}${bars('Gender overview','Female, male and unknown · active users.',b('gender'),'activeUsers','gender')}${bars('Active users by interest','One visitor can belong to several interest groups.',b('interests'),'activeUsers','interests')}${bars('Language',sub,b('language'),'activeUsers','language')}${bars('Location · city',sub,b('city'),'activeUsers','city')}${bars('Location · country',sub,b('country'),'activeUsers','country')}</div>`;
 if(tab==='technology')body=`<div class="notice">Device and screen details use fictional examples. Live availability varies; unavailable phone models remain unknown. A visitor using multiple devices can appear in several rows.</div><div class="grid equal">${bars('Device category','Mobile, desktop and tablet · active users.',b('device'),'activeUsers','device')}${bars('Operating system',sub,b('os'),'activeUsers','os')}${bars('Browser',sub,b('browser'),'activeUsers','browser')}${bars('Mobile phones & device models',sub,b('model'),'activeUsers','model')}${bars('Screen resolution','Reported screen sizes · active users.',b('resolution'),'activeUsers','resolution')}</div>`;
 if(tab==='acquisition')body=`<div class="metrics">${metric('New users',num(s.newUsers),'First visit during the selected dates','people','digital-breakdown','data-dimension="new"')}${metric('Returning users',num(s.returningUsers),'At least one repeat visit in this period','refresh','digital-breakdown','data-dimension="returning"')}${metric('Page views',num(s.views),'Views across selected sessions','globe','digital-breakdown','data-dimension="all"')}${metric('Avg. engagement / session',s.sessions?Math.round(s.seconds/s.sessions)+'s':'—','Sample engagement time','clock','digital-breakdown','data-dimension="all"')}</div><div class="grid equal">${bars('Traffic acquisition','Sessions grouped by the channel of each visit.',b('channel'),'sessions','channel')}${bars('User acquisition','New users grouped by first-user channel; selected session-channel filter still applies.',websiteBreakdown(rows.filter(r=>r.newUser),'firstChannel'),'newUsers','firstChannel')}</div>${panel('Channel performance','Session acquisition, website engagement and key events.',table(['Channel','#Sessions','#Active users','#Engagement','#Key events'],b('channel').map(r=>'<tr>'+td(btn(esc(r.label),'digital-breakdown',`data-dimension="channel" data-label="${esc(r.label)}"`,'ghost'))+td(num(r.sessions),true)+td(num(r.activeUsers),true)+td(pct(r.engaged,r.sessions),true)+td(num(r.keyEvents),true)+'</tr>')))}<p class="footnote">Active users across channels and new / returning audiences may overlap. Website key events are not signed leases.</p>`;
 return controls()+heading('Website Analytics','Understand who visits, which devices they use, and where traffic comes from.',btn('GA4 connection plan','digital-plan','data-service="ga4"','secondary'),'Marketing Intelligence')+`<div class="digital-source"><span class="digital-dot"></span> Demo dataset · Google Analytics is not connected</div>`+tabs('website',[['overview','Overview'],['demographics','Demographics'],['technology','Technology'],['acquisition','Acquisition']])+body;
 }
 function userMix(s){return `<div class="digital-user-mix"><div><small>New users</small><strong>${num(s.newUsers)}</strong></div><div><small>Returning users</small><strong>${num(s.returningUsers)}</strong></div><div><small>Active users</small><strong>${num(s.activeUsers)}</strong></div></div>`;}
 const accountLabel=accountCoverage;
 function social(tabName){kind='social';const available=selectAccounts(accounts,{...scope(),account:'all'});if(local.account!=='all'&&!available.some(a=>a.id===local.account))local.account='all';const signature=JSON.stringify([scope(),accounts.map(a=>[a.id,a.sample])]);if(signature!==feedSignature){feedSignature=signature;feedPage=0;}tab=['overview','feed','accounts'].includes(tabName)?tabName:'overview';const selected=selectAccounts(accounts,scope()),rows=socialRows(accounts,scope()),s=socialSummary(rows),posts=socialFeedSelection(accounts,scope(),feedSearch,feedFormat);feedPage=Math.min(feedPage,Math.max(0,Math.ceil(posts.length/9)-1));const count=n=>rows.length?num(n):'—';let body='';
 if(tab==='overview'){
 const trend=[...new Set(rows.map(r=>r.date))].sort().map(date=>({label:date.slice(5),date,value:rows.filter(r=>r.date===date).reduce((n,r)=>n+r.views,0)}));
 body=`<div class="metrics">${metric('Content / listing views',count(s.views),'Non-unique views across selected accounts','globe','digital-social-detail','data-measure="views"')}${metric('Interactions',count(s.interactions),'Sample likes, comments, saves or listing actions','message','digital-social-detail','data-measure="interactions"')}${metric('Website / listing clicks',count(s.clicks),'Sample outbound clicks','target','digital-social-detail','data-measure="clicks"')}${metric('Followers',local.platform==='Facebook Marketplace'?'N/A':count(s.followers),'Latest snapshot per Instagram / Facebook account','people','digital-social-detail','data-measure="followers"')}</div>${chart('Social activity over time','Daily views; repeat views are included.',trend)}<div class="grid digital-platform-grid">${platforms.filter(p=>local.platform==='all'||local.platform===p).map(p=>{const pr=rows.filter(r=>r.platform===p),ps=socialSummary(pr),pts=[...new Set(pr.map(r=>r.date))].sort().map(date=>({label:date.slice(5),value:pr.filter(r=>r.date===date).reduce((n,r)=>n+r.views,0)}));return panel(p,p==='Facebook Marketplace'?'Listing views, clicks and enquiries · demo / manual tracking.':'Account performance · fictional sample.',`<div class="digital-platform-total">${ps.accounts?num(ps.views):'—'}<small>${p==='Facebook Marketplace'?'listing':'content'} views</small></div><div class="digital-mini-bars" role="img" aria-label="${esc(p)} daily views">${pts.map(d=>`<span style="height:${Math.max(3,d.value/Math.max(1,...pts.map(v=>v.value))*55)}px" title="${d.label}: ${d.value}"></span>`).join('')}</div><div class="row"><span>Interactions</span><strong>${ps.accounts?num(ps.interactions):'—'}</strong></div><div class="row"><span>Clicks</span><strong>${ps.accounts?num(ps.clicks):'—'}</strong></div>${p==='Facebook Marketplace'?`<div class="row"><span>Sample enquiries</span><strong>${ps.accounts?num(ps.enquiries):'—'}</strong></div>`:`<div class="row"><span>Followers</span><strong>${ps.accounts?num(ps.followers):'—'}</strong></div>`}${btn('View '+p+' feed →','digital-platform',`data-platform="${esc(p)}"`,'secondary')}`);}).join('')}</div><p class="footnote">Shared management-company accounts are counted once and remain company-wide when viewing one property. No property-level allocation is implied. Followers are account totals, not unique people across platforms.</p>`;
 }else if(tab==='feed')body=panel('Property & management-company feed',`${posts.length} sample posts / listings · filter by property, company, dates or platform.`,`${feedControls(posts.length)}${displaySwitch('social-feed','Feed view')}<div class="digital-feed ${displayMode('social-feed')==='list'?'digital-feed-list':''}">${posts.slice(feedPage*9,feedPage*9+9).map(p=>{const a=accounts.find(a=>a.id===p.account);return `<article class="digital-post"><button type="button" class="digital-post-art ${a.platform==='Facebook Marketplace'?'marketplace':a.platform==='Facebook'?'facebook':'instagram'}" data-action="digital-post" data-id="${esc(p.id)}"><span>${esc(p.format)}</span><strong>${esc(p.title)}</strong><small>Illustrative post preview</small></button><div class="digital-post-body"><div>${chip(a.platform)}<small>${p.date}</small></div><h3>${esc(a.label)}</h3><p>@${esc(a.handle)} · ${esc(accountLabel(a))}</p><div class="digital-post-stats"><span>${num(p.views)} views</span><span>${num(p.interactions)} interactions</span></div>${btn('View post details →','digital-post',`data-id="${esc(p.id)}"`,'ghost')}</div></article>`;}).join('')||'<div class="empty">No feed items for this selection. Newly mapped handles will remain empty until connected.</div>'}</div>${feedPagination(posts.length)}`);
 else body=panel('Account & handle mapping','Map an account to a property, its manager, or a management company. Company accounts cover its properties.',table(['Account','Platform','Owner / coverage','Status','Actions'],selected.map(a=>'<tr>'+td(`<strong>${esc(a.label)}</strong><small>@${esc(a.handle)}</small>`)+td(esc(a.platform))+td(esc(accountLabel(a)))+td(chip(a.sample?'Sample account':'Not connected',a.sample?'':'warn'))+td((a.url?`<a class="btn secondary small" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Open profile ↗</a> `:'')+btn('Edit','digital-account',`data-id="${esc(a.id)}"`,'secondary small')+' '+btn('Remove','digital-account-remove',`data-id="${esc(a.id)}"`,'ghost small'))+'</tr>')),btn('+ Map account','digital-account'))+`<div class="notice">Saving a handle stores its mapping in this browser. It does not authorize Meta or fetch posts. New handles have no generated performance data. ${btn('How feeds connect →','digital-plan','data-service="meta"','ghost')}</div>`;
 return controls()+heading('Social Media','See content, community engagement and rental discovery across your portfolio.',btn('+ Map account','digital-account'),'Marketing Intelligence')+`<div class="digital-source"><span class="digital-dot"></span> Demo analytics & feed · ${selected.length} account mappings · No live social accounts connected ${btn('Integration plan','digital-plan','data-service="meta"','ghost small')}</div>`+tabs('social',[['overview','Overview'],['feed','Content feed'],['accounts','Accounts & handles']])+(!selected.length?'<div class="notice">No accounts match these property and platform filters.</div>':!rows.length&&tab==='overview'?'<div class="notice">No performance data is available for this selection. Disconnected handles have no analytics; sample activity is available only in September–October 2026.</div>':'')+body;
 }

 function feedControls(total){return `<div class="digital-feed-toolbar"><form id="digital-feed-search"><label class="sr-only" for="digital-feed-query">Search posts and handles</label><input id="digital-feed-query" name="search" value="${esc(feedSearch)}" placeholder="Search posts, handles or managers…" maxlength="160"><button class="btn secondary" type="submit">Search</button></form>${select('format','Content format',feedFormat,[['all','All formats'],['Video','Video'],['Photo','Photo'],['Listing','Listing']])}${btn('Clear feed filters','digital-feed-clear','','ghost')}<small role="status">${total} matching posts</small></div>`;}
 function feedPagination(total){return `<div class="pagination"><span>${total?feedPage*9+1:0}–${Math.min(total,(feedPage+1)*9)} of ${total} posts</span><div>${btn('Previous','digital-feed-page',`data-step="-1" ${feedPage===0?'disabled':''}`,'secondary small')}${btn('Next','digital-feed-page',`data-step="1" ${(feedPage+1)*9>=total?'disabled':''}`,'secondary small')}</div></div>`;}
 function accountForm(id){const a=accounts.find(a=>a.id===id)||{platform:'Instagram',label:'',handle:'',url:'',ownerType:'property',ownerId:filters.property==='all'?properties[0].id:filters.property};openDialog(id?'Edit account mapping':'Map a social account','Choose the property, property manager or company responsible for this handle.',`<form id="digital-account-form" data-id="${esc(id||'')}"><div class="event-form-grid"><div class="field"><label for="account-platform">Platform</label><select id="account-platform" name="platform">${options(platforms.map(n=>[n,n]),a.platform)}</select></div><div class="field"><label for="account-label">Account name</label><input id="account-label" name="label" required maxlength="100" value="${esc(a.label)}"></div><div class="field"><label for="account-handle">Handle / listing owner</label><input id="account-handle" name="handle" required maxlength="100" value="${esc(a.handle)}" placeholder="propertyliving"></div><div class="field"><label for="account-owner">Property, manager or company</label><select id="account-owner" name="owner">${options([...properties.map(p=>['property:'+p.id,p.name]),...properties.map(p=>['person:'+p.id,p.owner+' · '+p.name+' (property manager)']),...[...new Set(properties.map(p=>p.pmc))].map(p=>['manager:'+p,p+' (company-wide)'])],a.ownerType+':'+a.ownerId)}</select></div></div><div class="field"><label for="account-url">Profile or listing URL (optional)</label><input id="account-url" type="url" name="url" value="${esc(a.url)}" placeholder="https://www.instagram.com/propertyliving/"></div><p class="notice">Mapping only. Your handle stays disconnected until a live integration is implemented and authorized.</p><p class="date-error" role="alert"></p><div class="dialog-actions">${btn('Cancel','close','','secondary')}<button type="submit" class="btn">Save mapping</button></div></form>`);}
 function persistAccounts(next){localStorage.setItem(KEY,JSON.stringify(next));accounts=next;}
 function plan(service){const ga=service==='ga4';openDialog(ga?'Connect Google Analytics 4':'Connect social accounts & property feeds','Implementation plan · live authorization is not implemented in this prototype.',`<div class="definition-list">${ga?'<h3>1. Authorize reporting access</h3><p>Connect an authorized Google account and select GA4 property IDs. Map each property ID and website hostname to the corresponding MF Hub property.</p><h3>2. Sync aggregate reports</h3><p>Use the GA4 Data API for audience, technology, acquisition and website activity. Preserve unknown values, data thresholds, reporting identity and account timezone.</p><h3>3. Reconcile and refresh</h3><p>Check totals against GA4, cache reports server-side, and show the last successful refresh and any sync errors.</p>':'<h3>1. Map account ownership</h3><p>Save Instagram handles and Facebook Page IDs against a property or management company. Shared company feeds are shown once, with their full coverage.</p><h3>2. Authorize Meta access</h3><p>A live connector requires eligible professional Instagram accounts and Facebook Pages, approved permissions and secure server-side tokens. A handle alone does not grant access.</p><h3>3. Sync posts and supported metrics</h3><p>Fetch permitted account media / Page posts, retain post IDs and links, and refresh supported insights. Show stale, expired or disconnected states explicitly.</p><h3>Facebook Marketplace</h3><p>This prototype uses sample listing activity. Treat Marketplace as manual / approved import tracking unless a permitted integration is confirmed for the account and use case. A general live Marketplace feed is not implemented.</p>'}</div><p class="footnote">${ga?'<a href="https://developers.google.com/analytics/devguides/reporting/data/v1" target="_blank" rel="noopener noreferrer">GA4 Data API documentation</a>':'<a href="https://developers.facebook.com/docs/instagram-platform/" target="_blank" rel="noopener noreferrer">Instagram platform documentation</a> · <a href="https://developers.facebook.com/docs/pages-api/" target="_blank" rel="noopener noreferrer">Facebook Pages documentation</a>'}</p>`);}

 function saveCsv(data,filename){const url=URL.createObjectURL(new Blob(['\uFEFF'+csv(data)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported sample report for the current filters.');}
 function download(){const f=scope(),data=kind==='website'?websiteExportRows(f):socialExportRows(accounts,f,tab,feedSearch,feedFormat);saveCsv(data,`MF-Hub-${kind}-${tab}-${f.dateFrom}-${f.dateTo}.csv`);}

 function action(b){const {action,id}=b.dataset;if(!action?.startsWith('digital-'))return false;try{
 if(action==='digital-reset'){feedSearch='';feedFormat='all';feedPage=0;Object.assign(filters,{property:'all',pmc:'all',city:'all'});local={range:'10',dateFrom:'2026-10-01',dateTo:'2026-10-31',channel:'all',platform:'all',account:'all'};render();}
 else if(action==='digital-export')download();
 else if(action==='digital-open'){feedSearch='';feedFormat='all';feedPage=0;const {start,end}=reportingRange(b.dataset.from?{dateFrom:b.dataset.from,dateTo:b.dataset.to}:filters);Object.assign(local,{range:'custom',dateFrom:start,dateTo:end,channel:'all',platform:'all',account:b.dataset.account||'all'});navigate(b.dataset.route);}
 else if(action==='digital-feed-page'){feedPage=Math.max(0,feedPage+Number(b.dataset.step));render();}
 else if(action==='digital-feed-clear'){feedSearch='';feedFormat='all';feedPage=0;render();}
 else if(action==='digital-plan')plan(b.dataset.service);
 else if(action==='digital-platform'){local.platform=b.dataset.platform;navigate('social/feed');}
 else if(action==='digital-account')accountForm(id);
 else if(action==='digital-account-remove')openDialog('Remove account mapping?','This removes the local mapping, not the social account.',`<div class="dialog-actions">${btn('Cancel','close','','secondary')}${btn('Remove mapping','digital-account-confirm',`data-id="${esc(id)}"`,'danger')}</div>`);
 else if(action==='digital-account-confirm'){persistAccounts(accounts.filter(a=>a.id!==id));closeDialog();render();toast('Mapping removed from this browser.');}
 else if(action==='digital-breakdown'){const key=b.dataset.dimension,label=b.dataset.label;let rows=selectWebsite(scope());if(key==='new')rows=rows.filter(r=>r.newUser);else if(key==='returning')rows=rows.filter(r=>!r.newUser);else if(label)rows=rows.filter(r=>(key!=='firstChannel'||r.newUser)&&(Array.isArray(r[key])?r[key].includes(label):r[key]===label));const s=websiteSummary(rows);openDialog(label||'Website activity details',`${local.dateFrom} – ${local.dateTo} · Fictional website sample`,table(['Metric','#Value'],Object.entries({Sessions:s.sessions,'Active users':s.activeUsers,'New users':s.newUsers,'Returning users':s.returningUsers,'Engaged sessions':s.engaged,'Page views':s.views,'Key events':s.keyEvents}).map(([k,v])=>'<tr>'+td(k)+td(num(v),true)+'</tr>'))+'<p class="footnote">New and returning audiences can overlap. These are website visits, not CRM enquiries.</p>');}
 else if(action==='digital-social-detail'){const rows=socialRows(accounts,scope()),measure=b.dataset.measure;openDialog('Social performance by account','Fictional sample · current property, date and platform filters.',table(['Account','Platform','#'+measure],selectAccounts(accounts,scope()).map(a=>{const v=socialSummary(rows.filter(r=>r.account===a.id));return '<tr>'+td(esc(a.label))+td(esc(a.platform))+td(!v.accounts?'No data':measure==='followers'&&a.platform==='Facebook Marketplace'?'N/A':num(v[measure]),true)+'</tr>';})));}
 else if(action==='digital-post'){const p=socialPosts(accounts,scope()).find(p=>p.id===id);if(p){const a=accounts.find(a=>a.id===p.account);openDialog(esc(p.title),`${esc(a.platform)} · ${p.date} · Illustrative sample`,`${chip(p.format)}<p class="digital-post-caption">Discover life at ${esc(a.label)}. Explore available homes, shared spaces and the neighbourhood.</p><p>@${esc(a.handle)} · ${esc(accountLabel(a))}</p><div class="digital-user-mix"><div><small>Views</small><strong>${num(p.views)}</strong></div><div><small>Interactions</small><strong>${num(p.interactions)}</strong></div><div><small>Clicks</small><strong>${num(p.clicks)}</strong></div></div><p class="notice">Illustrative post only. No content was fetched from or published to this account.</p>`);}}
 }catch(error){toast(error.message);}return true;}
 function change(el){const key=el.dataset.digital;if(!key)return false;if(key==='range'){local.range=el.value;if(el.value==='all'){local.dateFrom='2026-09-01';local.dateTo='2026-10-31';}else if(el.value!=='custom'){const {start,end}=reportingRange({month:Number(el.value)});local.dateFrom=start;local.dateTo=end;}}else if(key==='format'){feedFormat=el.value;feedPage=0;}else if(['channel','platform','account'].includes(key))local[key]=el.value;render();document.getElementById(el.id)?.focus();return true;}
 function submit(e){if(!['digital-dates','digital-account-form','digital-feed-search'].includes(e.target.id))return false;e.preventDefault();const form=e.target;try{const values=Object.fromEntries(new FormData(form));if(form.id==='digital-feed-search'){feedSearch=String(values.search||'').trim().slice(0,160);feedPage=0;render();}else if(form.id==='digital-dates'){reportingRange(values);Object.assign(local,values);render();}else {const [ownerType,...owner]=values.owner.split(':'),account=validateAccount({...values,ownerType,ownerId:owner.join(':')},accounts,form.dataset.id||undefined),next=accounts.filter(a=>a.id!==account.id).concat(account);persistAccounts(next);if(!selectAccounts([account],{...scope(),platform:'all',account:'all'}).length)Object.assign(filters,{property:'all',pmc:'all',city:'all'});local.account=account.id;local.platform=account.platform;closeDialog();navigate('social/accounts');render();toast('Mapping saved in this browser. Account is not connected.');}}catch(error){form.querySelector('[role="alert"]').textContent=error.message;}return true;}
 function reset(){persistAccounts(seedAccounts());feedSearch='';feedFormat='all';feedPage=0;local={range:'10',dateFrom:'2026-10-01',dateTo:'2026-10-31',channel:'all',platform:'all',account:'all'};}
 const websiteScope=f=>{const {start,end}=reportingRange(f);return {...f,dateFrom:start,dateTo:end,channel:'all'};};
 const websiteData=f=>websiteSummary(selectWebsite(websiteScope(f)));
 const websiteTraffic=f=>chart('Website traffic','Daily sessions from the same sample dataset as Website Analytics.',websiteTrend(selectWebsite(websiteScope(f)),websiteScope(f)),'Sessions');
 const socialScope=f=>{const {start,end}=reportingRange(f);return {...f,dateFrom:start,dateTo:end,platform:'all',account:'all'};};
 const socialData=f=>socialSummary(socialRows(accounts,socialScope(f)));
 const socialContent=f=>socialPosts(accounts,socialScope(f)).map(p=>({...p,accountName:accounts.find(a=>a.id===p.account)?.label||''}));
 const exportWebsite=f=>{const q=websiteScope(f);saveCsv(websiteExportRows(q),`MF-Hub-website-${q.dateFrom}-${q.dateTo}.csv`);};
 const exportSocial=f=>{const q=socialScope(f);saveCsv(socialExportRows(accounts,q),`MF-Hub-social-overview-${q.dateFrom}-${q.dateTo}.csv`);};
 return {website,social,action,change,submit,reset,websiteData,websiteTraffic,socialData,socialContent,exportWebsite,exportSocial};
}
